<?php
namespace App\Models;use Illuminate\Database\Eloquent\Concerns\HasUuids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;
final class PolicyIssuanceRequest extends Model{use HasUuids;protected$fillable=['tenant_id','proposal_id','payment_intent_id','carrier_id','delegated_authority_agreement_id','status','authority_snapshot','terms_hash','coverage_starts_at','coverage_ends_at','requested_by','approved_by','approved_at','carrier_reference','rejection_reason','verified_by','verified_at','first_approved_by','first_approved_at','correction_reason','correction_requested_by','correction_requested_at'];protected function casts():array{return['authority_snapshot'=>'array','coverage_starts_at'=>'datetime','coverage_ends_at'=>'datetime','approved_at'=>'datetime','verified_at'=>'datetime','first_approved_at'=>'datetime','correction_requested_at'=>'datetime'];}public function proposal():BelongsTo{return$this->belongsTo(Proposal::class);}public function payment():BelongsTo{return$this->belongsTo(PaymentIntentRecord::class,'payment_intent_id');}public function carrier():BelongsTo{return$this->belongsTo(Carrier::class);}}
